/**
 * JavaScript wrapper for Audio Index WASM module
 * Provides a clean API for using the C++ library in the browser
 * Serverless version for docs folder (GitHub Pages)
 */

class AudioIndexWASM {
    constructor() {
        this.module = null;
        this.initialized = false;
    }

    /**
     * Initialize the WASM module
     * @returns {Promise<void>}
     */
    async initialize() {
        if (this.initialized) {
            return;
        }

        console.log('Loading Audio Index WASM module...');
        
        try {
            // Load the module (generated by Emscripten with -sEXPORT_ES6=1)
            // Path relative to docs/js/core/ -> ../../wasm/audio-index.js
            const AudioIndexModule = (await import('../../wasm/audio-index.js')).default;
            
            // Initialize with cache-busting for the .wasm file
            // Update this version number whenever you rebuild the WASM module
            const wasmVersion = '6';
            this.module = await AudioIndexModule({
                locateFile: (path) => {
                    if (path.endsWith('.wasm')) {
                        return `../../wasm/${path}?v=${wasmVersion}`;
                    }
                    return path;
                }
            });
            
            this.initialized = true;
            console.log('✓ Audio Index WASM module loaded successfully');
            console.log('Available functions:', Object.keys(this.module).filter(k => typeof this.module[k] === 'function'));
        } catch (error) {
            console.error('Failed to load WASM module:', error);
            throw error;
        }
    }

    /**
     * Ensure module is initialized before use
     * @private
     */
    _ensureInitialized() {
        if (!this.initialized) {
            throw new Error('WASM module not initialized. Call initialize() first.');
        }
    }

    /**
     * Calculate expected audio size for given parameters
     * @param {number} durationSeconds - Duration in seconds
     * @param {number} sampleRate - Sample rate (default: 44100)
     * @param {number} bitDepth - Bit depth (default: 16)
     * @param {number} channels - Channel count (default: 1)
     * @returns {number} Size in bytes
     */
    calculateAudioSize(durationSeconds, sampleRate = 44100, bitDepth = 16, channels = 1) {
        this._ensureInitialized();

        return this.module.calculateSize(
            durationSeconds,
            sampleRate,
            bitDepth,
            channels
        );
    }

    /**
     * Reconstruct audio data from a base64 index
     * @param {string} base64Index - Base64-encoded index (URL-safe, no padding)
     * @returns {Uint8Array} PCM sample data
     */
    reconstructAudioFromIndex(base64Index) {
        this._ensureInitialized();

        const result = this.module.reconstructAudio(base64Index);
        if (!result) {
            throw new Error('Failed to reconstruct audio from index');
        }
        return result;
    }

    /**
     * Convert audio samples to WAV format (client-side)
     * @param {Uint8Array} samples - PCM samples
     * @param {number} sampleRate - Sample rate
     * @param {number} bitDepth - Bit depth
     * @param {number} channels - Channel count
     * @returns {Blob} WAV file blob
     */
    samplesToWav(samples, sampleRate = 44100, bitDepth = 16, channels = 1) {
        const bytesPerSample = bitDepth / 8;
        const blockAlign = channels * bytesPerSample;
        const byteRate = sampleRate * blockAlign;
        const dataSize = samples.length;
        const fileSize = 44 + dataSize;

        // Create WAV buffer
        const buffer = new ArrayBuffer(fileSize);
        const view = new DataView(buffer);

        // Write WAV header
        const writeString = (offset, str) => {
            for (let i = 0; i < str.length; i++) {
                view.setUint8(offset + i, str.charCodeAt(i));
            }
        };

        writeString(0, 'RIFF');
        view.setUint32(4, fileSize - 8, true);
        writeString(8, 'WAVE');
        writeString(12, 'fmt ');
        view.setUint32(16, 16, true); // fmt chunk size
        view.setUint16(20, 1, true); // PCM format
        view.setUint16(22, channels, true);
        view.setUint32(24, sampleRate, true);
        view.setUint32(28, byteRate, true);
        view.setUint16(32, blockAlign, true);
        view.setUint16(34, bitDepth, true);
        writeString(36, 'data');
        view.setUint32(40, dataSize, true);

        // Write sample data
        const dataView = new Uint8Array(buffer, 44);
        dataView.set(samples);

        return new Blob([buffer], { type: 'audio/wav' });
    }

    /**
     * Create an Audio element from reconstructed samples
     * @param {Uint8Array} samples - PCM samples
     * @param {number} sampleRate - Sample rate
     * @param {number} bitDepth - Bit depth
     * @returns {HTMLAudioElement} Audio element ready to play
     */
    createAudioElement(samples, sampleRate = 44100, bitDepth = 16) {
        const wavBlob = this.samplesToWav(samples, sampleRate, bitDepth, 1);
        const url = URL.createObjectURL(wavBlob);
        const audio = new Audio(url);
        
        // Clean up object URL when audio is loaded
        audio.addEventListener('loadeddata', () => {
            URL.revokeObjectURL(url);
        });

        return audio;
    }
}

// Export for use in modules
export default AudioIndexWASM;

// Also make available globally for non-module scripts
if (typeof window !== 'undefined') {
    window.AudioIndexWASM = AudioIndexWASM;
}

console.log('✅ audioIndexWasm.js loaded - WASM wrapper ready');
